# Add tests for new function
import { median } from './stats';

describe('median', () => {
  it('should calculate the median of an even number of values', () => {
    expect(median([1, 2])).toBe(1.5);
  });

  it('should calculate the median of an odd number of values', () => {
    expect(median([1, 2, 3])).toBe(2);
  });
});

